import json
import re
import html
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
refs = json.loads(Path('reference-targets.json').read_text())
answers = []
by_number = {}

def plain(xml):
    return html.unescape(re.sub(r'<[^>]+>', '', xml or ''))

def paragraph(text):
    return '<p>' + text + '</p>'

def replace_once(text, old, new):
    assert text.count(old) == 1, old
    return text.replace(old, new, 1)

def effect(kind, measure, description, before, after, population, conditions, sq, pq, unit='legal_duty'):
    return dict(kind=kind, measure_id=measure, description=description, before=before, after=after,
                unit=unit, affected_population=population, conditions_and_transition=conditions,
                replacement_or_new_burdens='Aucune obligation de remplacement, donnée, déclaration, autorisation ou délai nouveau ; les obligations autonomes expressément conservées gardent leur régime.',
                source_quote=sq, proposed_quote=pq)

def add(i, proposed, reason, notes, assessment, limits, effects=None, removed=None, classification=None, benefit=None, new_burdens=None, repeal=None):
    s = sources[i]
    a = {k:s[k] for k in ['code_id','source_id','source_sha256','number']}
    a.update(proposed_xml=proposed, reason=reason, review_notes=notes,
             status='retained_unchanged' if proposed is None else 'rewrite_draft')
    if proposed is None:
        a['classification'] = 'retained_necessary'
    if removed:
        a.update(change_type='normative_reduction', reform_policy_id='editorial_direction_2026_10_19', removed_provisions=removed)
    if repeal:
        a.update(change_type='full_repeal', repeal_policy_id='editorial_direction_2026_10_19', repeal_scope=repeal)
    a['substantive_impact'] = dict(version=1, classification=classification or ('retained_necessary' if proposed is None else 'material_reduction'),
        assessment=assessment, scope_limitations=limits,
        new_burdens_review=new_burdens or ('Aucune charge nouvelle identifiée : le texte source est intégralement maintenu, sans registre, donnée, délai ni condition ajouté.' if proposed is None else 'Aucune charge nouvelle identifiée : la proposition retire les seules contraintes décrites, sans déclaration, justificatif, autorisation ni registre de remplacement. Aucun solde global des codes n’est chiffré.'),
        effects=effects or [])
    if s.get('benefit_check_required'):
        assert benefit and len(benefit) >= 100
        a['benefit_review'] = benefit
    a['reference_checks'] = []
    answers.append(a)
    by_number[s['number']] = a
    return a

# 0 : Le prix des parts reste dû ; une dette distincte n'interdit plus l'accession.
x = sources[0]['source_xml']
old = "Tout locataire ou tout locataire associé ne peut acquérir des parts d'une société civile immobilière d'accession progressive à la propriété que s'il est à jour de toutes ses obligations locatives et, le cas échéant, de celles envers la société civile immobilière."
new = "La seule existence d'une dette locative ou d'une dette envers la société civile immobilière d'accession progressive à la propriété, distincte du prix des parts, ne peut faire obstacle à l'acquisition de parts par le locataire ou le locataire associé. Celui-ci reste tenu des autres obligations locatives et sociales auxquelles cette acquisition est légalement subordonnée. Les dettes correspondantes demeurent exigibles selon leur régime propre. Cette règle ne dispense pas du paiement du prix des parts."
x = replace_once(x, old, new)
x += paragraph("Le deuxième alinéa s'applique aux acquisitions de parts réalisées à compter de l'entrée en vigueur de la loi, y compris dans les sociétés déjà constituées. Les clauses statutaires qui subordonnent ces acquisitions au paiement préalable de dettes distinctes du prix des parts cessent de s'appliquer à ces acquisitions. Les créances, sûretés, compensations légalement admises et recours relatifs à ces dettes sont conservés ; les cessions antérieures ne sont pas remises en cause.")
add(0, x,
    "Réforme de fond : suppression de l'interdiction générale d'acquérir des parts en présence d'une dette locative ou sociale distincte du prix. Le paiement du prix, le recouvrement des dettes et les sûretés subsistent. Maintien intégral de l'acquisition de toutes les parts avant la propriété, des cessions ou échanges statutaires et du maintien dans les lieux après revente de toutes les parts.",
    "Coordonner le dernier alinéa de R443-9-2 et, dans l'annexe à R443-9-4 lue en entier, les articles 10, 3 (citation obligatoire de l'interdiction), 19 (suspension) et 24 (attribution). L443-6-9 est coordonné dans ce lot. La garantie de rachat de L443-6-6 et les compensations de R443-9-3 ne sont pas supprimées. Les créances ne sont ni remises ni différées. Les plafonds de ressources de L443-6-2 et le droit de rester locataire de R443-9-1 demeurent ; aucune condition nouvelle de solvabilité ne remplace l'interdiction retirée.",
    "La source officielle bloque toute nouvelle acquisition pour tout manquement locatif ou social. Ce blocage est retiré pour les opérations futures, sans effacement des sommes dues ; il s'agit d'une ouverture de l'accès à l'acquisition et non d'une baisse de dette.",
    "La mesure ne finance pas le prix des parts et ne garantit pas que l'accession soit abordable. Les clauses types et R443-9-2 restent à coordonner hors de ce lot ; aucun gain fiscal ou national n'est établi.",
    [effect('obligation_removed','sciap-acquisition-dettes-distinctes',"Retrait du préalable de paiement de toute dette distincte du prix pour acheter des parts.","Tout locataire ou associé doit être à jour de toutes ses obligations pour acquérir des parts.","Une dette locative ou sociale ne bloque plus à elle seule l'achat ; prix, dettes et sûretés subsistent.","Locataires et locataires associés des SCI d'accession progressive.","Acquisitions à compter de l'entrée en vigueur, y compris SCI existantes ; anciennes cessions et créances protégées.",old,"La seule existence d'une dette locative ou d'une dette envers la société civile immobilière d'accession progressive à la propriété, distincte du prix des parts, ne peut faire obstacle à l'acquisition de parts par le locataire ou le locataire associé.")],
    ["Le préalable général de paiement intégral de toutes les obligations locatives et sociales pour acquérir des parts, distinct du paiement du prix de ces parts."])

# 1 : Suppression de la période incompressible et du visa de cession anticipée.
x = sources[1]['source_xml']
old4 = "L'organisme d'habitations à loyer modéré, associé-gérant, peut aliéner au profit du locataire associé la totalité des parts du lot représentatif de son logement au terme d'un délai de dix ans à compter de la construction ou de l'acquisition de l'immeuble par l'organisme d'habitations à loyer modéré."
new4 = "L'organisme d'habitations à loyer modéré, associé-gérant, peut aliéner au profit du locataire associé la totalité des parts du lot représentatif de son logement sans durée minimale depuis la construction ou l'acquisition de l'immeuble par cet organisme."
old5 = "L'aliénation de la totalité des parts d'un lot avant le délai défini au quatrième alinéa du présent article peut être autorisée par décision motivée du représentant de l'Etat dans le département d'implantation du logement, après consultation de la commune d'implantation. Le remboursement de tout ou partie des aides accordées par l'Etat pour la construction, l'acquisition ou l'amélioration de ce logement est exigible selon des modalités fixées par l'autorité administrative."
