assert len(answers) == len(sources) == 24
for a,s in zip(answers,sources):
    assert a['number']==s['number']
    for e in a['substantive_impact']['effects']:
        assert len(e['source_quote'])>=12 and e['source_quote'] in plain(s['source_xml']), (a['number'],'source',e['source_quote'])
        assert len(e['proposed_quote'])>=12 and e['proposed_quote'] in plain(a['proposed_xml']), (a['number'],'proposed',e['proposed_quote'])
    if a.get('removed_provisions'):
        assert all(len(t)>=30 for t in a['removed_provisions'])
    assert {c['target_key'] for c in a['reference_checks']}==set(refs['requirements'][a['code_id']+'|'+a['source_id']])
Path('answer.json').write_text(json.dumps(answers,ensure_ascii=False,indent=2)+'\n')
print('answer.json:',len(answers),'articles')
